{"source":"import json
import sys
from datetime import datetime, timezone

def parse_iso8601(s):
    """Parse an offset-aware ISO8601 string to a datetime with timezone."""
    if s is None:
        return None
    # Handle 'Z' suffix by replacing with '+00:00'
    if s.endswith('Z'):
        s = s[:-1] + '+00:00'
    # Try parsing with timezone info
    try:
        return datetime.fromisoformat(s)
    except ValueError:
        return None

def is_naive(dt):
    """Check if a datetime is naive (no timezone info)."""
    return dt.tzinfo is None

def format_utc(dt):
    """Format a datetime as YYYY-MM-DDTHH:MM:SSZ in UTC."""
    # Convert to UTC if it has timezone info
    if dt.tzinfo is not None:
        dt = dt.astimezone(timezone.utc)
    return dt.strftime('%Y-%m-%dT%H:%M:%SZ')

def main():
    input_file = sys.argv[1]
    with open(input_file, 'r') as f:
        data = json.load(f)

    as_of_str = data['as_of']
    as_of = parse_iso8601(as_of_str)
    if as_of is None:
        print(json.dumps([]))
        return

    reminders = data.get('reminders', [])
    result = []

    for r in reminders:
        # Skip completed reminders
        if r.get('completed', False):
            continue

        due_str = r.get('due')
        # Skip null/missing due values
        if due_str is None:
            continue

        due_dt = parse_iso8601(due_str)
        # Skip naive datetimes (no timezone info)
        if due_dt is None or is_naive(due_dt):
            continue

        # Check if due AT OR BEFORE as_of
        if due_dt <= as_of:
            result.append({
                'id': r['id'],
                'title': r['title'],
                'due_utc': format_utc(due_dt)
            })

    # Sort by actual due instant (we need to re-parse for sorting) 
    # Actually, we can sort by the parsed datetime stored implicitly
    # Let's restructure to keep the datetime for sorting

    # Re-process to keep datetimes for sorting
    result_with_dt = []
    for r in reminders:
        if r.get('completed', False):
            continue
        due_str = r.get('due')
        if due_str is None:
            continue
        due_dt = parse_iso8601(due_str)
        if due_dt is None or is_naive(due_dt):
            continue
        if due_dt <= as_of:
            result_with_dt.append((due_dt, r['id'], r['title']))

    # Sort by due instant then id
    result_with_dt.sort(key=lambda x: (x[0], x[1]))

    # Build final output
    final_result = [
        {'id': item[1], 'title': item[2], 'due_utc': format_utc(item[0])}
        for item in result_with_dt
    ]

    print(json.dumps(final_result))

if __name__ == '__main__':
    main()"}

